/**
 * Generate and persist a password entirely inside the paired local bridge.
 *
 * The model supplies only public card metadata and a generation policy. The
 * generated bytes exist in this process long enough to be sealed/sent to the
 * atomic Agent Secret write, and never cross the model-facing tool boundary,
 * argv, a file, the local mirror, logs or the returned receipt.
 */
import crypto from "node:crypto";
import { RuntimeProofPreparationError } from "./trelio-runtime-proof-preparation.mjs";

import {
  BridgePairingRequiredError,
  BridgePluginUpgradeRequiredError,
  ensureBridgeCompatibility,
  ensureCompanyEncryptionContext,
  request,
  requireToken,
  renderLocalFormPage,
} from "./trelio-workspace.mjs";
import {
  buildLocalAgentSecretWrite,
  buildLocalSecretRequestFingerprint,
  normalizeAgentSecretNewCard,
  protectNewSecretMetadata,
} from "./trelio-secret-chat.mjs";

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/iu;
const FIELD_KEY = /^[a-z][a-z0-9_]{0,63}$/u;
const PASSWORD_LENGTH_MIN = 16;
const PASSWORD_LENGTH_MAX = 128;
const PASSWORD_GROUPS = [
  "abcdefghijkmnopqrstuvwxyz",
  "ABCDEFGHJKLMNPQRSTUVWXYZ",
  "23456789",
  "!#$%&()*+,-./:;<=>?@[]^_{|}~",
];
const PASSWORD_ALPHABET = PASSWORD_GROUPS.join("");
const INPUT_KEYS = new Set([
  "secretId", "runId", "expectedCurrentVersion", "clientRequestId",
  "newSecret", "generatedFields", "userExplicitlyRequestedGeneratedPersistentStorage",
]);
const SAFE_NATIVE_FAILURES = new Map([
  ["TRELIO_RUNTIME_HOOK_REQUIRED", "Включите Hooks плагина Trelio Agent Workspaces и повторите запрос."],
  ["AGENT_RUNTIME_POLICY_NOT_SATISFIED", "Выберите разрешённую компанией модель и уровень reasoning, затем начните новую сессию с включёнными Hooks."],
  ["MCP_REAUTHORIZATION_REQUIRED", "Вызовите list_agent_secrets для исходной области через подключение Trelio: оно покажет штатное расширение OAuth-доступа. Сохраните ранее выданные scopes и повторите генерацию с тем же clientRequestId."],
]);

export class AgentSecretGenerateError extends Error {
  constructor(code, message) {
    super(message);
    this.code = code;
  }
}

const invalid = () => {
  // The failure is intentionally independent of public input details so it
  // stays safe if a future caller accidentally mixes in sensitive material.
  throw new AgentSecretGenerateError(
    "AGENT_SECRET_GENERATE_INPUT_INVALID",
    "Проверьте цель, password-поля, длину и явную просьбу сгенерировать и сохранить доступы.",
  );
};
const isRecord = (value) => Boolean(value && typeof value === "object" && !Array.isArray(value));
const boundedString = (value, maximum) => (
  typeof value === "string" && value.length > 0 && value.length <= maximum
);
const canonicalJson = (value) => JSON.stringify(
  value,
  function (_key, item) {
    if (!isRecord(item)) return item;
    return Object.fromEntries(Object.keys(item).sort().map((key) => [key, item[key]]));
  },
);

export const normalizeGeneratedAgentSecretInput = (input) => {
  if (
    !isRecord(input) || Object.keys(input).some((key) => !INPUT_KEYS.has(key))
    || input.userExplicitlyRequestedGeneratedPersistentStorage !== true
    || !UUID.test(input.runId || "")
    || !Number.isSafeInteger(input.expectedCurrentVersion) || input.expectedCurrentVersion < 0
    || !boundedString(input.clientRequestId, 255) || input.clientRequestId !== input.clientRequestId.trim()
    || Boolean(input.secretId) === Boolean(input.newSecret)
    || !Array.isArray(input.generatedFields) || input.generatedFields.length < 1 || input.generatedFields.length > 50
  ) invalid();
  if (input.secretId && !UUID.test(input.secretId)) invalid();
  let newSecret;
  if (input.newSecret) {
    try {
      newSecret = normalizeAgentSecretNewCard(input.newSecret, input.expectedCurrentVersion);
    } catch {
      invalid();
    }
  }
  const keys = new Set();
  const generatedFields = input.generatedFields.map((field) => {
    if (
      !isRecord(field) || Object.keys(field).some((key) => !["key", "generator", "length"].includes(key))
      || !FIELD_KEY.test(field.key || "") || keys.has(field.key)
      || field.generator !== "password"
      || !Number.isSafeInteger(field.length)
      || field.length < PASSWORD_LENGTH_MIN || field.length > PASSWORD_LENGTH_MAX
    ) invalid();
    keys.add(field.key);
    return { key: field.key, generator: "password", length: field.length };
  });
  if (newSecret && (
    generatedFields.some((field) => !newSecret.fields.some((candidate) => (
      candidate.key === field.key && candidate.type === "password"
    )))
    || newSecret.fields.some((field) => field.required && !keys.has(field.key))
  )) invalid();
  return { ...input, ...(newSecret ? { newSecret } : {}), generatedFields };
};

const buildGenerationKey = ({ context, companyEncryption, token }) => {
  const key = context.storageMode === "company_e2ee"
    ? Buffer.from(companyEncryption?.scopePrivateEncryptionKey?.privateJwk?.d || "", "base64url")
    : Buffer.from(token || "", "utf8");
  if (!key.length) invalid();
  return key;
};

const createDeterministicIndexSource = (key, seed) => {
  let block = Buffer.alloc(0);
  let offset = 0;
  let counter = 0;
  const nextByte = () => {
    if (offset >= block.length) {
      // HMAC expansion makes an ambiguous retry reproduce the same password
      // without persisting plaintext. Each request is separated by the exact
      // company/member/card/Run/version/policy seed assembled by the caller.
      block.fill(0);
      const counterBytes = Buffer.allocUnsafe(4);
      counterBytes.writeUInt32BE(counter++);
      block = crypto.createHmac("sha256", key)
        .update("trelio:generated-agent-secret-password:v1\0")
        .update(seed)
        .update(counterBytes)
        .digest();
      offset = 0;
    }
    return block[offset++];
  };
  return {
    next(length) {
      // Rejection sampling avoids modulo bias for alphabets whose length does
      // not divide 256, including the combined password alphabet.
      const ceiling = Math.floor(256 / length) * length;
      let byte = nextByte();
      while (byte >= ceiling) byte = nextByte();
      return byte % length;
    },
    dispose() {
      block.fill(0);
      offset = 0;
    },
  };
};

export const generateDeterministicPassword = ({ key, seed, length }) => {
  const source = createDeterministicIndexSource(key, seed);
  try {
    // Force one character from every class, then shuffle the entire result so
    // class positions reveal nothing and downstream password rules stay met.
    const characters = PASSWORD_GROUPS.map((group) => group[source.next(group.length)]);
    while (characters.length < length) {
      characters.push(PASSWORD_ALPHABET[source.next(PASSWORD_ALPHABET.length)]);
    }
    for (let index = characters.length - 1; index > 0; index--) {
      const other = source.next(index + 1);
      [characters[index], characters[other]] = [characters[other], characters[index]];
    }
    return characters.join("");
  } finally {
    source.dispose();
  }
};

export const normalizeGeneratedPasswordPolicy = (fields, generatedFields) => {
  if (!Array.isArray(generatedFields) || generatedFields.length < 1 || generatedFields.length > 50
    || generatedFields.some(field => !isRecord(field) || Object.keys(field).some(key => !["key", "generator", "length"].includes(key))
      || !FIELD_KEY.test(field.key ?? "") || field.generator !== "password"
      || !Number.isSafeInteger(field.length) || field.length < PASSWORD_LENGTH_MIN || field.length > PASSWORD_LENGTH_MAX)) invalid();
  if (
    !Array.isArray(fields) || fields.length < 1 || fields.length > 50
    || fields.some((field) => (
      !FIELD_KEY.test(field.key || "") || typeof field.required !== "boolean"
    ))
    || new Set(fields.map((field) => field.key)).size !== fields.length
  ) invalid();
  const requested = new Map(generatedFields.map((field) => [field.key, field]));
  if (
    requested.size !== generatedFields.length
    || generatedFields.some((field) => !fields.some((candidate) => (
      candidate.key === field.key && candidate.type === "password"
    )))
    || fields.some((field) => field.required && !requested.has(field.key))
  ) invalid();

  return fields.flatMap(field => requested.has(field.key) ? [requested.get(field.key)] : []);
};

/** SAME HMAC password engine for human and managed-device callers. Binding is
 * assembled by the admitted host, not a model-supplied seed/key or generator. */
export const generateAgentSecretPasswordValues = ({ key, policy, seed }) => Object.fromEntries(policy.map(field => [field.key,
  generateDeterministicPassword({ key, seed: `${seed}\0${field.key}\0${field.length}`, length: field.length })]));

export const buildGeneratedAgentSecretWrite = async ({ input, context, companyEncryption, token }) => {
  const fields = input.newSecret?.fields ?? context.fields;
  const policy = normalizeGeneratedPasswordPolicy(fields, input.generatedFields);
  // Normalize generation order to the schema, so a semantically identical
  // retry does not change the derived bytes merely because JSON array order did.
  const key = buildGenerationKey({ context, companyEncryption, token });
  let values;
  try {
    const commonSeed = canonicalJson({
      companyId: context.companyId,
      memberId: context.companyMemberId,
      secretId: context.secretId,
      runId: input.runId,
      expectedCurrentVersion: input.expectedCurrentVersion,
      clientRequestId: input.clientRequestId,
      newSecret: input.newSecret ?? null,
      policy,
    });
    values = generateAgentSecretPasswordValues({ key, policy, seed: commonSeed });
  } finally {
    key.fill(0);
  }
  return buildLocalAgentSecretWrite({
    input, context, companyEncryption, token, values, source: "generated",
  });
};

export const handleGeneratedAgentSecretSave = async (
  origin,
  rawInput,
  {
    signal,
    getToken = requireToken,
    checkCompatibility = ensureBridgeCompatibility,
    getEncryptionContext = ensureCompanyEncryptionContext,
    sendRequest = request,
    proofForSubmission = () => rawInput.runtimeSessionProof,
  } = {},
) => {
  try {
    signal?.throwIfAborted();
    const input = normalizeGeneratedAgentSecretInput(rawInput?.arguments);
    const companySlug = rawInput?.companySlug;
    if (!boundedString(companySlug, 120) || companySlug !== companySlug.trim() || rawInput.localFilePath !== undefined) invalid();
    const token = await getToken(origin, { onStatus: () => undefined, signal });
    await checkCompatibility(origin, token, { signal });
    const query = new URLSearchParams({
      companySlug, runId: input.runId, clientRequestId: input.clientRequestId,
      ...(input.newSecret
        ? { scopeType: input.newSecret.scopeType, scopeId: input.newSecret.scopeId }
        : { secretId: input.secretId }),
    });
    const context = await (await sendRequest(
      origin,
      token,
      "/api/agent-secrets/generated-save-context?" + query,
      { signal },
    )).json();
    if (context.companySlug !== companySlug) invalid();
    let companyEncryption = null;
    if (context.storageMode === "company_e2ee") {
      try {
        companyEncryption = await getEncryptionContext({
          origin, token, company: { id: context.companyId, slug: companySlug },
        });
      } catch {
        throw new AgentSecretGenerateError(
          "AGENT_SECRET_DEVICE_NOT_READY",
          "Локальное устройство не готово к шифрованию. Проверьте его доступ в настройках шифрования компании, затем повторите генерацию с тем же clientRequestId.",
        );
      }
    }
    const transport = await buildGeneratedAgentSecretWrite({
      input, context, companyEncryption, token,
    });
    signal?.throwIfAborted();
    const proof = proofForSubmission();
    const result = await (await sendRequest(
      origin,
      token,
      "/api/agent-workspaces/company-context/" + encodeURIComponent(companySlug) + "/actions/execute",
      {
        method: "POST", headers: { "content-type": "application/json" }, signal,
        body: JSON.stringify({
          nativeTool: "generate_agent_secret", arguments: transport,
          ...(proof ? { runtimeSessionProof: proof } : {}),
        }),
      },
    )).json();
    const outcome = result.structuredContent;
    if (result.isError && SAFE_NATIVE_FAILURES.has(outcome?.code)) {
      throw new AgentSecretGenerateError(outcome.code, SAFE_NATIVE_FAILURES.get(outcome.code));
    }
    if (
      result.isError || outcome?.ok !== true || outcome.secret?.id !== context.secretId
      || outcome.secret?.storageMode !== context.storageMode || outcome.secret?.hasValue !== true
      || outcome.secret?.currentVersion !== input.expectedCurrentVersion + 1
    ) {
      throw new AgentSecretGenerateError(
        "AGENT_SECRET_GENERATE_SAVE_REJECTED",
        "Генерация и сохранение не подтверждены. Проверьте разрешения, активный запуск и текущую версию карточки; повтор использует тот же clientRequestId.",
      );
    }
    const safe = {
      ok: true,
      secret: {
        id: context.secretId,
        storageMode: context.storageMode,
        currentVersion: outcome.secret.currentVersion,
        hasValue: true,
      },
      replayed: outcome.replayed === true,
      setupUrl: new URL(
        "/" + encodeURIComponent(companySlug) + "/agent-secrets/" + context.secretId + "/setup/",
        origin,
      ).href,
    };
    return {
      structuredContent: safe,
      content: [{ type: "text", text: "Пароль сгенерирован и сохранён. Значение не раскрывалось модели." }],
    };
  } catch (error) {
    if (error instanceof BridgePairingRequiredError || error instanceof BridgePluginUpgradeRequiredError
      || error instanceof RuntimeProofPreparationError) {
      throw error;
    }
    const safe = error instanceof AgentSecretGenerateError
      ? { code: error.code, message: error.message }
      : {
          code: "AGENT_SECRET_GENERATE_SAVE_UNCONFIRMED",
          message: error?.statusCode === 403
            ? "Нет разрешения на генерацию и сохранение. Проверьте права на карточку, активный запуск и доступ локального устройства."
            : "Генерация и сохранение не подтверждены. Проверьте подключение, локальное устройство и текущую карточку перед повтором с тем же clientRequestId.",
        };
    return { isError: true, structuredContent: safe, content: [{ type: "text", text: safe.message }] };
  }
};

/** Managed generation reuses the SAME model-free generator/fingerprint and
 * Secret writer. Only a native sealed create+generate decision admits this
 * host callback. An opaque requireToken handle is never generation material.
 * Preflight/read-back occurs BEFORE key access; uncertain write is not retried. */
export const handleAssistantGeneratedPrivateSecret = async ({ origin, input, scope, token,
  withGenerationKey, sendRequest = request }) => {
  const receipt = result => {
    if (!isRecord(result) || result.created !== true || result.secret?.id !== input.clientRequestId
      || result.secret?.scopeType !== "assistant" || result.secret?.currentVersion !== 1 || result.secret?.hasValue !== true) invalid();
    // Project only structural receipt fields even if a broken upstream ever
    // adds a value/fingerprint to its response. Never echo a native object.
    return { created: true, secret: { id: result.secret.id, scopeType: "assistant", currentVersion: 1, hasValue: true } };
  };
  const query = new URLSearchParams(Object.fromEntries(Object.entries(input).map(([key,value])=>
    [key,key==='neutralPlan'?JSON.stringify(value):value])));
  const context = await (await sendRequest(origin, token,
    "/api/agent-secrets/generated-save-context?" + query)).json();
  if (context?.completed === true) {
    if (!isRecord(context.receipt) || Object.keys(context).sort().join(",") !== "completed,receipt") invalid();
    return receipt(context.receipt);
  }
  if (!isRecord(context) || context.schemaVersion !== 1 || context.completed !== false
    || context.secretId !== input.clientRequestId || context.runId !== input.runId
    || ["assistantUserId", "deviceId", "companyId", "taskId"].some(key => context[key] !== scope[key])
    || typeof withGenerationKey !== "function") invalid();
  const policy = normalizeGeneratedPasswordPolicy(context.fields, context.generatedFields);
  // The exact owner decision, assistant/device, company/task, original Run and
  // schema all separate the existing protected device key's HMAC domain.
  return withGenerationKey(async key => {
    const binding = { ...scope, ...input, secretId: context.secretId, fields: context.fields, policy };
    const values = generateAgentSecretPasswordValues({ key, policy, seed: canonicalJson(binding) });
    const requestFingerprint = buildLocalSecretRequestFingerprint({ key, source: "assistant_generated", binding: { ...binding, values } });
    try {
      const result = await (await sendRequest(origin, token,
        `/api/agent-secrets/secrets/${context.secretId}/value-from-bridge`, {
          method: "PUT", headers: { "content-type": "application/json" },
          body: JSON.stringify({ ...input, expectedCurrentVersion: 0, requestFingerprint, values }),
        })).json();
      return receipt(result);
    } finally {
      // Like the ordinary human primitive, immutable JS strings live only in
      // this protected invocation; no file, clipboard or model output is used.
      for (const key of Object.keys(values)) delete values[key];
    }
  });
};

/** NEW company/private cards through the SAME protected producer and genuine
 * Secret HTTP profile. Only native-neutral metadata enters this local path.
 * Company metadata/value and global private keyring AAD stay independent.
 * Preflight proves current ACL/Run and reads a committed receipt before key or
 * human input. No response failure retries begin/save or reopens a form. */
export const handleAssistantNewSecretCreation = async ({origin,input,scope,token,withGenerationKey,
  companyEncryption=null,onContext=()=>undefined,sendRequest=request,collectValues}) => {
  const personal=input.holder==='assistant';
  if(personal&&input.plan?.valueSource!=='protected_input')invalid();
  const receipt=result=>{
    const secret=result?.receipt?.secret;
    if(personal){
      if(result?.completed!==true||result.receipt?.created!==true||secret?.id!==input.clientRequestId
        ||secret.holder!=='assistant'||secret.scopeType!=='assistant'||secret.storageMode!=='trelio'
        ||secret.currentVersion!==1||secret.hasValue!==true)invalid();
      return {created:true,secret:{id:secret.id,holder:'assistant',scopeType:'assistant',storageMode:'trelio',currentVersion:1,hasValue:true}};
    }
    if(result?.completed!==true||result.receipt?.created!==true||!UUID.test(secret?.id??'')||secret.holder!=='company'
      ||secret.companyId!==scope.companyId||secret.scopeType!=='task'||secret.scopeId!==scope.taskId
      ||secret.currentVersion!==(input.plan.valueSource==='empty'?0:1)||secret.hasValue!==(input.plan.valueSource!=='empty')
      ||secret.storageMode!==(companyEncryption?'company_e2ee':'trelio')
      ||result.receipt.setupPath!==undefined&&(typeof result.receipt.setupPath!=='string'
        ||!new RegExp(`^/[a-z0-9][a-z0-9_-]{0,119}/agent-secrets/${secret.id}/setup/$`,'u').test(result.receipt.setupPath)))invalid();
    return {created:true,secret:{id:secret.id,holder:'company',companyId:scope.companyId,scopeType:'task',scopeId:scope.taskId,
      storageMode:secret.storageMode,currentVersion:secret.currentVersion,hasValue:secret.hasValue},setupPath:result.receipt.setupPath};
  };
  const read=async()=>{
    const query=new URLSearchParams(Object.entries(input).map(([key,value])=>[key,key==='plan'?JSON.stringify(value):value]));
    return (await sendRequest(origin,token,'/api/agent-secrets/generated-save-context?'+query)).json();
  };
  const context=await read();
  if(context?.completed===true)return receipt(context);
  if(context?.pending===true)throw new AgentSecretGenerateError('ASSISTANT_SECRET_INPUT_ATTEMPT_UNCERTAIN',
    'Предыдущий ввод или сохранение не подтверждены. Проверьте исходный запрос; форма повторно не открывается.');
  if(!isRecord(context)||context.schemaVersion!==1||context.completed!==false||!UUID.test(context.secretId??'')
    ||context.runId!==input.runId||['assistantUserId','deviceId','companyId','taskId'].some(key=>context[key]!==scope[key])
    ||context.valueSource!==input.plan.valueSource||!personal&&(context.scopeType!=='task'||context.scopeId!==scope.taskId)
    ||context.storageMode!==(!personal&&companyEncryption?'company_e2ee':'trelio')||!isRecord(context.metadata)
    ||context.metadata.name!==(personal?'Personal secret':'Company secret')||personal&&context.secretId!==input.clientRequestId||typeof withGenerationKey!=='function')invalid();
  await onContext(context);
  const endpoint=`/api/agent-secrets/secrets/${context.secretId}/value-from-bridge`;
  const post=async body=>(await sendRequest(origin,token,endpoint,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(body)})).json();
  const newSecret={...context.metadata,scopeType:'task',scopeId:scope.taskId};
  const save=async(values,key)=>{
    if(personal){
      // Global private values use the SAME native private keyring/AAD. Only
      // the surrounding task question uses company E2EE; never wrap these
      // bytes with company metadata/value markers or send a holder override.
      const requestFingerprint=buildLocalSecretRequestFingerprint({key,source:'protected_input',
        binding:{...scope,...input,secretId:context.secretId,fields:context.fields,values}});
      return receipt(await post({...input,secretId:context.secretId,stage:'save',expectedCurrentVersion:0,requestFingerprint,values}));
    }
    let localWrite;
    if(input.plan.valueSource==='empty'){
      const protectedMetadata=companyEncryption?await protectNewSecretMetadata(newSecret,context,companyEncryption):null;
      localWrite={companySlug:context.companySlug,contentProtection:companyEncryption?'company_e2ee_v1':'server_keyring_v1',
        requestFingerprint:buildLocalSecretRequestFingerprint({key,source:'assistant_generated',binding:{...scope,...input,secretId:context.secretId,metadata:newSecret}}),
        fieldKeys:[],values:{},newSecret:protectedMetadata?.card??newSecret,
        ...(protectedMetadata?{encryptedPayloads:[protectedMetadata.payload]}:{})};
    }else{
      const transport=await buildLocalAgentSecretWrite({input:{runId:input.runId,clientRequestId:input.clientRequestId,expectedCurrentVersion:0,newSecret},
        context,companyEncryption,token,values,source:input.plan.valueSource==='generated'?'generated':'protected_input',fingerprintKey:key});
      // Human API permission flags are NOT authority here. The native adapter
      // independently checks the original persisted owner decision and source.
      localWrite=transport.localWrite;
    }
    const {newSecret:card,...write}=localWrite;
    return receipt(await post({...input,secretId:context.secretId,stage:'save',expectedCurrentVersion:0,...write,
      name:card.name,publicDescription:card.publicDescription,templateType:card.templateType,fields:card.fields}));
  };
  try{return await withGenerationKey(async key=>{
    if(input.plan.valueSource==='protected_input'){
      if(context.protectedInputStorageSupported!==true)invalid();
      const started=await post({...input,secretId:context.secretId,stage:'begin'});
      if(started?.started!==true||started.secretId!==context.secretId)throw new AgentSecretGenerateError('ASSISTANT_SECRET_INPUT_ATTEMPT_UNCERTAIN',
        'Ввод не допущен либо уже был начат. Форма повторно не открывается.');
      const collect=collectValues??collectAgentSecretThroughProtectedForm;
      let result;
      await collect({origin,fields:context.fields,holder:personal?'assistant':'company',persistValues:async values=>{
        // Reread original pending attempt after human delay. Neither a stale
        // form nor logout/Run expiry can skip the native final ACL/owner CAS.
        const current=await read();
        if(current?.completed===true){result=receipt(current);return;}
        if(current?.pending!==true||current.secretId!==context.secretId)invalid();
        result=await save(values,key);
      }});
      if(!result)invalid();return result;
    }
    const policy=input.plan.valueSource==='generated'?normalizeGeneratedPasswordPolicy(context.fields,context.generatedFields):null;
    const values=policy?generateAgentSecretPasswordValues({key,policy,seed:canonicalJson({...scope,...input,secretId:context.secretId,fields:context.fields,policy})}):{};
    try{return await save(values,key);}finally{for(const field of Object.keys(values))delete values[field];}
  });
  }catch(error){
    // An observed transport/form failure is never a writer retry. A single
    // exact structural read-back may prove that the original atomic write
    // committed; otherwise keep the pending latch and original failure.
    try{const recovered=await read();if(recovered?.completed===true)return receipt(recovered);}catch{}
    throw error;
  }
};

// Preserve the existing company adapter import; both holders execute the one
// implementation above, not another form/HTTP/credential engine.
export const handleAssistantCompanySecretCreation=handleAssistantNewSecretCreation;

/** Human-entered values use the SAME protected loopback and renderer as PAT
 * setup. This is an internal host callback, never an MCP value/file producer.
 * Native callers must first persist their exact one-use capture-attempt latch,
 * then pass only the native-reviewed schema. A form opening is not a save.
 * Both corporate and personal holders share this implementation; their native
 * ACL, owner intent, AAD and atomic writer remain separate and authoritative. */
export const collectAgentSecretThroughProtectedForm = async ({
  origin, fields, holder, persistValues, ...formOptions
}) => {
  const fail = () => { throw new AgentSecretGenerateError("AGENT_SECRET_PROTECTED_INPUT_INVALID",
    "Проверьте полную схему и заполните обязательные поля. Значения не передаются в чат."); };
  if (!["company", "assistant"].includes(holder) || typeof persistValues !== "function"
    || !Array.isArray(fields) || fields.length < 1 || fields.length > 50
    || fields.some(field => !isRecord(field) || !FIELD_KEY.test(field.key || "") || ["nonce", "decision"].includes(field.key)
      || !boundedString(field.label, 120) || typeof field.required !== "boolean"
      || !["username", "password", "token", "text", "key", "certificate", "totp"].includes(field.type))
    || new Set(fields.map(field => field.key)).size !== fields.length) fail();
  // Existing loopback input is capped at 32 KiB of URL-encoded data. Keep its
  // bound, rather than enlarging a credential transport for this adapter:
  // at most 8 KiB JSON plus percent encoding, 50 fixed keys, nonce/decision.
  const maximumValueBytes = 8 * 1024;
  const { collectCredentialThroughLoopback } = await import("./trelio-remote-mcp.mjs");
  const allowed = new Set(["nonce", "decision", ...fields.map(field => field.key)]);
  return collectCredentialThroughLoopback(origin, {}, {
    ...formOptions,
    allowCancel: true,
    terminalPersistenceFailure: true,
    renderForm: ({ nonce, errorMessage }) => renderLocalFormPage({
      title: "Сохранить доступы",
      description: holder === "company" ? "Новый секрет компании для этой задачи" : "Новый личный секрет ассистента",
      sections: [{ paragraphs: ["Введите значения здесь. Они не попадут в чат. Общий размер – до 8 КиБ.",
        "Эта форма не извлекает данные из браузера, аккаунтов или файлов."],
      ...(errorMessage ? { notice: { tone: "error", text: "Проверьте обязательные поля и общий размер значений." } } : {}),
      fields: fields.map(field => ({ name: field.key, label: field.label,
        type: ["certificate", "key", "text"].includes(field.type) ? "textarea"
          : field.type === "username" ? "text" : "password",
        required: field.required, maxLength: maximumValueBytes, autocomplete: "off" })),
      }],
      form: { action: "/credential", nonce, actions: [
        { label: "Сохранить", name: "decision", value: "save" },
        { label: "Отмена", name: "decision", value: "cancel", variant: "secondary", formNoValidate: true },
      ] },
    }),
    parseSubmission: form => {
      if (form.get("decision") !== "save" || [...form.keys()].some(key => !allowed.has(key))
        || [...allowed].some(key => form.getAll(key).length > 1)) fail();
      const values = Object.create(null);
      for (const field of fields) {
        // Password whitespace and newlines are meaningful; never trim values.
        const value = form.get(field.key);
        if (field.required && (typeof value !== "string" || value.length === 0)) fail();
        values[field.key] = value === null || value === "" ? null : value;
      }
      if (Buffer.byteLength(JSON.stringify(values), "utf8") > maximumValueBytes) fail();
      return values;
    },
    doctorCredential: async () => {},
    persistCredential: async (_origin, _resolved, values) => {
      try { await persistValues(values); }
      finally {
        // Immutable JS/browser strings cannot be zeroed. Drop all host object
        // references immediately; no draft, disk, mirror or model output.
        for (const key of Object.keys(values)) delete values[key];
      }
    },
    successTitle: "Сохранено",
    successMessage: "Trelio подтвердил сохранение секрета. Эту вкладку можно закрыть.",
  });
};
